        if ( processorClassPaths.isEmpty() ) {
            processorClassloader = DEFAULT_PROCESSOR_CLASSLOADER;
        }
        else {
            processorClassloader = new ModifiableURLClassLoader(
                newFilteringClassLoaderForJdk()
